using System.Runtime.InteropServices;
using OpenMagicMouse.Gestures;

namespace OpenMagicMouse.Scrolling;

/// <summary>
/// Dedicated high-priority WH_MOUSE_LL hook that suppresses coarse hardware
/// WM_MOUSEWHEEL / WM_MOUSEHWHEEL ticks generated by applewirelessmouse.sys
/// while Magic Mouse 2 capacitive touch frames are actively scrolling, leaving
/// cursor movement and any external USB mouse wheel completely untouched.
/// </summary>
public sealed class LowLevelWheelFilter : IDisposable
{
    private const int WhMouseLl = 14;
    private const int WmMouseWheel = 0x020A;
    private const int WmMouseHWheel = 0x020E;
    private const uint WmQuit = 0x0012;
    private const uint LlmhfInjected = 0x00000001;

    private readonly LowLevelMouseProc _hookProc;
    private readonly Thread _hookThread;
    private readonly ManualResetEventSlim _readyEvent = new(false);

    private nint _hookHandle;
    private uint _nativeThreadId;
    private int _enabled = 1;
    private long _suppressUntilMs;
    private bool _disposed;

    public bool IsInstalled { get; private set; }

    public bool Enabled
    {
        get => Volatile.Read(ref _enabled) != 0;
        set => Volatile.Write(ref _enabled, value ? 1 : 0);
    }

    public LowLevelWheelFilter()
    {
        _hookProc = HookCallback;
        _hookThread = new Thread(HookThreadMain)
        {
            IsBackground = true,
            Name = "OpenMagicMouse.WheelFilter",
            Priority = ThreadPriority.Highest
        };
        _hookThread.Start();
        _readyEvent.Wait(1500);
    }

    public void NotifyMagicMouseTouch(long _ = 0)
    {
        Volatile.Write(ref _suppressUntilMs, Environment.TickCount64 + 220);
    }

    private void HookThreadMain()
    {
        _nativeThreadId = GetCurrentThreadId();
        _hookHandle = SetWindowsHookExW(WhMouseLl, _hookProc, GetModuleHandleW(null), 0);
        IsInstalled = _hookHandle != nint.Zero;
        _readyEvent.Set();

        if (!IsInstalled)
        {
            return;
        }

        try
        {
            while (GetMessageW(out MSG msg, nint.Zero, 0, 0) > 0)
            {
                TranslateMessage(ref msg);
                DispatchMessageW(ref msg);
            }
        }
        finally
        {
            if (_hookHandle != nint.Zero)
            {
                UnhookWindowsHookEx(_hookHandle);
                _hookHandle = nint.Zero;
            }
        }
    }

    private unsafe nint HookCallback(int nCode, nint wParam, nint lParam)
    {
        if (nCode >= 0 && Enabled && (wParam == WmMouseWheel || wParam == WmMouseHWheel) && lParam != nint.Zero)
        {
            var info = *(MSLLHOOKSTRUCT*)lParam;
            if (info.dwExtraInfo != ActionExecutor.MagicScrollExtraInfo &&
                (info.flags & LlmhfInjected) == 0 &&
                Environment.TickCount64 <= Volatile.Read(ref _suppressUntilMs))
            {
                return 1;
            }
        }

        return CallNextHookEx(_hookHandle, nCode, wParam, lParam);
    }

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        Enabled = false;

        if (_nativeThreadId != 0)
        {
            PostThreadMessageW(_nativeThreadId, WmQuit, 0, 0);
        }

        try { _hookThread.Join(500); } catch { }
        _readyEvent.Dispose();
    }

    [UnmanagedFunctionPointer(CallingConvention.Winapi)]
    private delegate nint LowLevelMouseProc(int nCode, nint wParam, nint lParam);

    [StructLayout(LayoutKind.Sequential)]
    private struct POINT
    {
        public int x;
        public int y;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct MSLLHOOKSTRUCT
    {
        public POINT pt;
        public uint mouseData;
        public uint flags;
        public uint time;
        public nint dwExtraInfo;
    }

    [StructLayout(LayoutKind.Sequential)]
    private struct MSG
    {
        public nint hwnd;
        public uint message;
        public nuint wParam;
        public nint lParam;
        public uint time;
        public POINT pt;
        public uint lPrivate;
    }

    [DllImport("user32.dll", SetLastError = true)]
    private static extern nint SetWindowsHookExW(int idHook, LowLevelMouseProc lpfn, nint hMod, uint dwThreadId);

    [DllImport("user32.dll", SetLastError = true)]
    private static extern bool UnhookWindowsHookEx(nint hhk);

    [DllImport("user32.dll")]
    private static extern nint CallNextHookEx(nint hhk, int nCode, nint wParam, nint lParam);

    [DllImport("user32.dll")]
    private static extern int GetMessageW(out MSG lpMsg, nint hWnd, uint wMsgFilterMin, uint wMsgFilterMax);

    [DllImport("user32.dll")]
    private static extern bool TranslateMessage(ref MSG lpMsg);

    [DllImport("user32.dll")]
    private static extern nint DispatchMessageW(ref MSG lpMsg);

    [DllImport("user32.dll", SetLastError = true)]
    private static extern bool PostThreadMessageW(uint idThread, uint msg, nuint wParam, nint lParam);

    [DllImport("kernel32.dll", CharSet = CharSet.Unicode)]
    private static extern nint GetModuleHandleW(string? lpModuleName);

    [DllImport("kernel32.dll")]
    private static extern uint GetCurrentThreadId();
}
